sketches.source:
setcpm(70/4)

// The ground: C G Am Em F C F G, two notes per chord
const theme = note("<[e5 g5 d5 b4 c5 e5 b4 g4 a4 c5 g4 e4 a4 f4 g4 b4] [c5 e5 b4 d5 e5 a5 g5 e5 f5 a5 e5 g5 c5 a4 b4 d5] [g5 e5 d5 g5 a5 e5 b5 g5 a5 f5 g5 c6 a5 f5 d5 b4] [c5@2 b4@2 a4@2 g4@2 f4@2 e4@2 f4 a4 g4 b4]>")

// First violin states each variation
violin1: theme.s("sawtooth").vib(5.5).vibdepth(.12)
  .attack(.03).decay(.2).sustain(.6).release(.15)
  .lpf(3200).pan(.3).room(.5).gain(.24)

// Second violin follows one cycle behind, an octave down
violin2: theme.late(1).add(-12).s("sawtooth").vib(5).vibdepth(.1)
  .attack(.03).decay(.2).sustain(.6).release(.15)
  .lpf(2600).pan(.7).room(.5).gain(.22)

// Viola enters two cycles behind, a softer reed colour
viola: theme.late(2).add(-12).s("triangle").timbre("reed")
  .attack(.03).sustain(.5).release(.2).room(.5).gain(.14)

// Cello walks the ground bass, harpsichord fills in the harmony
cello: note("c3 g2 a2 e2 f2 c2 f2 g2").s("sawtooth").lpf(700)
  .attack(.04).decay(.3).sustain(.5).release(.2).room(.4).gain(.32)
harpsichord: note("[c4,e4,g4] [b3,d4,g4] [a3,c4,e4] [b3,e4,g4] [a3,c4,f4] [g3,c4,e4] [a3,c4,f4] [b3,d4,g4]")
  .s("square").pw(.15).attack(.002).decay(.2).sustain(0).release(.1)
  .lpf(3000).room(.3).gain(.12)

setcpm(72/3)

// One cycle is a bar of 3/4
// Music box melody: C G F C Dm F G C
musicbox: note("<[e5 g5 c6] [b5@2 g5] [a5 c6 a5] [g5@3] [f5 a5 d6] [c6@2 a5] [g5 b5 d6] [c6@3]>")
  .s("sine").fm(2).fmh(4)
  .attack(.002).decay(.8).sustain(0).release(1)
  .room(.6).size(.8).gain(.3)

// Oom-pah-pah on a soft keyboard
waltz: note("<[c3 [e3,g3] [e3,g3]] [g2 [b2,d3] [b2,d3]] [f2 [a2,c3] [a2,c3]] [c3 [e3,g3] [e3,g3]] [d3 [f3,a3] [f3,a3]] [f2 [a2,c3] [a2,c3]] [g2 [b2,d3] [b2,f3]] [c3 [e3,g3] ~]>")
  .s("triangle").timbre("soft")
  .attack(.005).decay(.4).sustain(0).release(.3).gain(.28)

// A parent humming along, an octave down
hum: note("<e4 d4 c4 e4 f4 a4 g4 c4>").s("hum").attack(.5).release(1.5).gain(.22)

// Crickets outside the nursery window
crickets: s("insect").slow(4).distance(6).gain(.1)

setcpm(96/4)

// Twelve-bar shuffle in A: every chord is its own bar
const a7 = note("[a1@2 a1] [c#2@2 c#2] [e2@2 e2] [f#2@2 e2]")
const d7 = note("[d2@2 d2] [f#2@2 f#2] [a2@2 a2] [b2@2 a2]")
const e7 = note("[e2@2 e2] [g#2@2 g#2] [b2@2 b2] [c#3@2 b2]")
const ka = note("[g3,a3,c#4,e4]")
const kd = note("[f#3,a3,c4,d4]")
const ke = note("[g#3,b3,d4,e4]")

// Boogie bass walking the changes
bass: cat(a7, a7, a7, a7, d7, d7, a7, a7, e7, d7, a7, e7)
  .s("sawtooth").lpf(650).lpq(2).decay(.25).sustain(.4).release(.1).gain(.5)

// Shuffle drums: triplet ride, backbeat and a lazy kick
drums: s("[bd@2 ~] [~@2 bd] [bd@2 ~] [~@2 bd?0.5], ~ sd ~ sd, [rd@2 rd]*4")
  .room(.25).gain(.7)

// Organ stabs on two and four, pushed by a triplet
organ: cat(ka, ka, ka, ka, kd, kd, ka, ka, ke, kd, ka, ke)
  .struct("~ [~@2 x] ~ [~@2 x]")
  .s("sawtooth").timbre("organ").lpf(1800)
  .decay(.3).sustain(.3).release(.15).pan(.35).gain(.25)

// Harmonica answers in the blues scale
harp: n("<[~ [~@2 6] [7@2 6] [4@2 3]] [[2@2 0] 0 ~ ~] [~ [3@2 4] [6@2 4] [3@2 2]] [0 ~ ~ [~@2 3]]>")
  .scale("A:blues").transpose(12)
  .s("sawtooth").timbre("reed").vowel("o")
  .mono(1).glide(.05).vib(5.5).vibdepth(.3)
  .attack(.03).sustain(.6).release(.2)
  .lpf(2600).pan(.65).room(.4).gain(.32)
